  bootstrap();CriticalMachineState s=state(CriticalMachineKind.ASSEMBLY);MTECriticalMachine machine=host(s);set(s,"owner",OWNER.toString());GuardWorld w=(GuardWorld)U.allocateInstance(GuardWorld.class);w.tile=(TileEntity)machine.getBaseMetaTileEntity();w.chunk=(Chunk)U.allocateInstance(Chunk.class);w.tile.setWorldObj(w);s.bindHost(w.tile);
