  for(String name:new String[]{"tier","kind","parallel","speed","economy","status","batch","duration"}){final String key=name;set(gui,name,new IntSyncValue(()->key.equals("kind")?s.getKind().ordinal():key.equals("tier")?s.getTier().ordinal():key.equals("status")?s.getState():key.equals("duration")?s.getBatchDuration():key.equals("batch")?s.getBatchProgress():0));}
