  click(line,0);selected.updateCacheFromSource(false);check(s.getProcessingMode().equals(CriticalProcessingModes.ASSEMBLY_LINE)&&((Boolean)get(gui,"lastActionAccepted")),"real dropdown left-click command selects authorized assembly-line mode");check(dropdown.getValue().getValue().equals(CriticalProcessingModes.ASSEMBLY_LINE),"dropdown display reads authoritative S2C selectedMode telemetry");
  set(s,"cycleDuration",400);click(assembly,0);check(s.getProcessingMode().equals(CriticalProcessingModes.ASSEMBLY_LINE)&&!((Boolean)get(gui,"lastActionAccepted")),"server dropdown guard rejects active duration even without legacy batchId");
  set(s,"cycleDuration",0);set(s,"batchId","paid");click(assembly,0);check(s.getProcessingMode().equals(CriticalProcessingModes.ASSEMBLY_LINE),"server dropdown guard rejects paid batchId even with zero duration");
  set(s,"batchId","");set(s,"state",1);click(assembly,0);check(s.getProcessingMode().equals(CriticalProcessingModes.ASSEMBLY_LINE),"BUILD state rejects mode replacement");
  set(s,"state",2);click(assembly,0);check(s.getProcessingMode().equals(RecipeMaps.assemblerRecipes.unlocalizedName),"READY idle state accepts assembler mode");
  manager.player=stranger;click(line,0);check(s.getProcessingMode().equals(RecipeMaps.assemblerRecipes.unlocalizedName)&&stranger.messages==1,"actual interaction handler rejects nonowner before command and reports permission");
  manager.player=owner;click(line,1);check(s.getProcessingMode().equals(RecipeMaps.assemblerRecipes.unlocalizedName),"actual interaction handler ignores nonleft mouse button");
  JsonObject o=new JsonObject();o.addProperty("status","PASS");o.addProperty("checks",checks);o.addProperty("GT",source(gregtech.api.recipe.RecipeMap.class));o.addProperty("product",source(MTECriticalMachineTerminalGui.class));o.addProperty("boundary","Actual dropdown construction and InteractionSyncHandler MouseData packet decode/server permission and batch guards; telemetry injected as real SyncValues; no full panel/render/network transport");Files.write(Paths.get(args[0]),new GsonBuilder().setPrettyPrinting().create().toJson(o).getBytes("UTF-8"));
